const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-125.410394, -41.729403]);
  const region = point.buffer(100000); // 100km radius

  // Time periods
  const currentStart = '2019-11-01';
  const currentEnd = '2020-02-29';
  const priorStart = '2018-11-01';
  const priorEnd = '2019-02-28';

  // 2. Data Acquisition
  function getChlorophyllData(startDate, endDate) {
    return ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
      .filterDate(startDate, endDate)
      .filterBounds(region)
      .select('chlor_a');
  }

  const currentCollection = getChlorophyllData(currentStart, currentEnd);
  const priorCollection = getChlorophyllData(priorStart, priorEnd);

  // Check collection sizes
  const currentSize = currentCollection.size().getInfo();
  const priorSize = priorCollection.size().getInfo();

  console.log(`Current period (${currentStart} to ${currentEnd}): ${currentSize} images`);
  console.log(`Prior period (${priorStart} to ${priorEnd}): ${priorSize} images`);

  if (currentSize === 0 || priorSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites and mask invalid values
  function processCollection(collection) {
    const meanImg = collection.mean();
    // Mask negative/zero values (chlorophyll should be positive)
    const masked = meanImg.updateMask(meanImg.gt(0));
    return masked;
  }

  const currentMean = processCollection(currentCollection);
  const priorMean = processCollection(priorCollection);

  // 4. Calculate statistics and check valid pixels
  function getStats(image, periodName) {
    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanVal = stats.get('chlor_a').getInfo();
    const count = stats.get('chlor_a_count').getInfo();

    console.log(`${periodName}: Mean=${meanVal ? meanVal.toFixed(4) : 'null'}, ValidPixels=${count}`);

    return {mean: meanVal, count: count};
  }

  const currentStats = getStats(currentMean, 'Current');
  const priorStats = getStats(priorMean, 'Prior');

  // 5. Validation & Final Answer
  if (currentStats.count === 0 || priorStats.count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (currentStats.mean === null || priorStats.mean === null || 
      isNaN(currentStats.mean) || isNaN(priorStats.mean)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if current period has higher chlorophyll
  const currentHigher = currentStats.mean > priorStats.mean;
  const diffPercent = ((currentStats.mean - priorStats.mean) / priorStats.mean * 100).toFixed(1);

  console.log(`Change: ${diffPercent}% (${currentHigher ? 'increase' : 'decrease'})`);

  if (currentHigher) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
